"""Render existing measured receipts; preserve the provenance of conditional board-recording costs."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent;R=ROOT/'results'
def j(p):return json.loads(p.read_text())
def table(head,rows):
    return '\n'.join(['| '+' | '.join(head)+' |','|'+'|'.join(['---']*len(head))+'|']+['| '+' | '.join(map(str,row))+' |' for row in rows])
def pct(v):return f'{100*v:.2f}%'
def main():
    paragraphs=['# Rust vector collector on Turtle v31g']
    say=paragraphs.append
    production=R/'parity-production.json';stress=R/'parity-256.json';par=production if production.exists() else stress
    if par.exists():
        r=j(par);n=r['counts']
        say(f'**The Rust and Python collectors produced byte-identical learner input** on {n["seat_decisions"]:,} sampled seat actions, including {n["frozen_decisions"]:,} frozen-seat decisions, {n["battles"]:,} combats and {n["matches"]:,} completed matches. Of {n["live_decisions"]:,} live actions, {n["delivered"]:,} reached complete live turns and {n["learner_decisions"]:,} were selected for the learner in {n["selected_batches"]} identical FIFO batches. Both sides discarded {n["stale"]:,} stale decisions, retained {n["queued"]:,} queued and ended with {n["pending"]:,} in unfinished turns. [Parity receipt](results/{par.name})')
        if production.exists():
            q=j(stress)['counts']
            say(f'The main check consumes the production target of 8,192 decisions and deterministically publishes three waves after selection. Separately, a deliberately over-fast publication clock advanced every 13 waves against a 1,024-decision target. That stress test generated {q["seat_decisions"]:,} seat actions, compared {q["delivered"]:,} completed live decisions, accepted {q["learner_decisions"]:,} and rejected {q["stale"]:,} as stale, identically on both engines. Both tests use the same world-seed start; their decision counts must not be described as independent unique matches. [Lag stress receipt](results/parity-256.json)')
    else:say('The independent CPU trajectory comparison is running. GPU work requires both its passing receipt and the operator’s GPU-FREE marker.')
    say('The comparison runs the recorded 14.35M 26,022 policy on CPU in FP32, sampling separately against each backend with the same PyTorch RNG state per wave. Both collectors independently maintain their GRU bank, Python slot IDs, parent and periodic snapshot assignments, turn buffers and lag-one FIFO. The live policy is held fixed; the deterministic publication schedule exercises version stamps, lag and snapshot retirement. This tests transport equivalence. In actual asynchronous training, publication races and BF16 batch shape can change which legal samples are selected.')
    say('At every step the check compares shape, dtype and bytes of all 15 public arrays on both seats, active flags, lives/wins, battle-resolved/result, rewards, terminal/winner, sampled triples, joint freeze masks, log probabilities, memory and episode policy IDs. It separately compares every completed and selected segment’s owned observations and bootstrap observations, action, freeze mask, behavior log probability/version, reward, discount, initial GRU, terminal flag, seat-relative battle label, slot ID, order and length. Rust int8 0/1 flags are viewed as bool and its double rewards are converted to the historical float32 trajectory type. Stale actor scratch on an inactive seat is converted to the native sentinel (−1,10,5) and freeze mask zero. All public observations alias the native outputs, and complete trajectories own their storage before reset. Invalid native status raises. [Adapter](rust_adapter.py) · [Boundary test](parity.py) · [Partial reset and illegal-input checks](results/adapter-check.json)')
    say('## Interface and board recording')
    gap=j(R/'missing-fields.json')['counts']
    say(f'Ordinary training requires no additional engine field. Exact board scoring requires both post-END, pre-combat teams, including trigger counts and the Parrot’s effective copy, even on terminal fights. The public history omits these two fields. The actual 25,772 board archive has {gap["battles_with_spent_triggers"]} fight with spent uses and {gap["battles_with_copy"]} fights with copied abilities in {gap["battles"]:,} battles; filling defaults would already change real records. Per-game turn can be tracked from reset and battle events. An actual battle seed is useful to audit and to design counterfactual sampling; the ordinary trainer and external ghost sampler do not require it. [Proposed field layout, types, sentinels and lifetime](interface.md) · [Archived examples](results/missing-fields.json) · [Validated event serializer](board_event.py) · [23,748 historical round-trips](results/codec.json)')
    if not (R/'proof/result.json').exists():
        say('## Resource gate')
        say('No native GPU throughput, proof score or new board-recording time is reported before the explicit release. The benchmark checks that marker on every invocation. The historical 2,693 learned/s and 21,938 acting/s are comparison values from the earlier report, not native measurements in this study.')
    else:
        d=j(R/'proof/result.json');choice=j(R/'selection.json')
        say('## GPU collection and learning')
        say(f'The throughput-selected real Rust configuration used **{choice["games"]} games**, ten Rust threads on CPUs 5–19, 8,192 live decisions/update, a half-update queue threshold, max version lag one and the parent arm’s historical four Adam rates. The continuation starts at immutable 25,772. Half of games are assigned frozen opponents; only live decisions enter learning. One hundred updates precede the first scheduled snapshot. The 100-update proof learned {d["learned"]:,} decisions at **{d["learned_s"]:,.0f}/s** ({(d["learned_s"]/2693-1)*100:+.1f}% versus 2,693), served **{d["seat_s"]:,.0f} seat decisions/s**, dropped **{pct(d["stale_share"])}** of learned-plus-rejected rows and had **{d["gpu"]:.1f}% GPU utilization**. This is a separate run; the historical comparison uses the previous fastest cohort collector on the same g rules. [Proof](results/proof/result.json) · [Width selection](results/selection.json)')
        rows=[]
        for f in sorted([*R.glob('act-*/result.json'),*R.glob('train-*/result.json'),R/'proof/result.json']):
            v=j(f);rows.append([f.parent.name,v['waves'],f"{v['seat_s']:,.0f}",f"{v['games_s']:.2f}",f"{v['learned_s']:,.0f}",pct(v['stale_share']) if v['training'] else '—',f"{v['gpu']:.1f}%"])
        say(table(['Run','Waves','Seat decisions/s','Completed matches/s','Learned/s','Stale','GPU util'],rows))
        peak=j(R/'act-4096/result.json');warm=peak['steady'] or peak
        say(f'At 4,096 simultaneous games, training off, the Rust path sustained {warm["seat_s"]:,.0f} acting decisions/s and {warm["games_s"]:.2f} completed games/s after the first cohort of completions. The matched historical replay ceiling was 21,938/s, making the real/replay ratio {warm["seat_s"]/21938:.3f}. Every game started from turn one. No game-length override was used.')
        times=d['main_seconds'];wall=d['wall']
        say(table(['Proof coordinator stage','% wall'],[[k,f'{100*v/wall:.1f}%'] for k,v in times.items()]+[['queue and loop remainder',f'{100*(1-sum(times.values())/wall):.1f}%'],['learner active, overlapping',f'{100*d["learner_wall"]/wall:.1f}%']]))
        say('Rust engine step includes legality, battle, settlement and all public observation encoding. Actor includes packing, the network and returning sampled actions. Learner wait includes publishing finished weights; the separate learner-active row overlaps coordinator stages. [Training module](collect_rust.py) · [Gated commands](phase.sh)')
    if (R/'strength.json').exists():
        s=j(R/'strength.json');lo,hi=s['ci95']
        say(f'**Head-to-head against frozen 25,772: {pct(s["score"])} [{pct(lo)}, {pct(hi)}]**, {s["wdl"]} W/D/L across {s["games"]:,} games, {s["pairs"]:,} seat-swapped independent seed pairs, greedy batch **{s["batch"]:,}** throughout. '+('The lower bound clears 50%.' if lo>=.5 else 'The entire interval is below 50%; the proof failed.' if hi<.5 else 'The interval spans 50%; it shows no statistically resolved decline and does not establish zero-margin non-regression.')+' No model or checkpoint was promoted. [Vector scorer receipt](results/strength.json)')
    if (R/'board.json').exists():
        b=j(R/'board.json');m=j(R/'board-rehearsal.json')
        say('## Outside yardstick and recording cost')
        say(f'The proof checkpoint’s independent ranked-board index is **{100*b["index"]:.2f}** on 1,000 complete greedy self-play matches, batch 128. The verified yardstick split, 4,000 ranked board pairs per turn and eight battle seeds per pair match the established protocol. Parent 25,772 scored 31.14, 31.06 and 30.70 across the three recorded replication seeds. These are separate samples, not a confidence interval on this checkpoint. [Official board receipt](results/board.json) · [Field comparisons](results/ghost.json)')
        say(table(['Turn',*b['scores']], [['Board score',*[pct(x) for x in b['scores'].values()]]]))
        say(f'The existing independent full recorder took {b["record_s"]:.1f} s plus {b["ghost_s"]:.1f} s for the ranked comparison. In a separate Rust-only rollout the same {m["matches"]:,} greedy games took {m["wall"]:.1f} s including extraction of public signatures, comparison with reference boards and writing the complete JSON payload; {m["matched_visible_boards_both_seats"]:,}/{m["battles"]:,} battle events matched on both visible teams. Hidden fields in the rehearsal payload came from the prior archive. At the measured payload and ghost costs, {m["wall"]+b["ghost_s"]:.1f} s/checkpoint is a **conditional planning figure** for a native event exporter. Its capture/ABI cost is unmeasured; the exact native scorer is unavailable on this pin. The official index uses a separate run of the reference recorder and no second environment is stepped in the Rust collector or rehearsal. [Recording rehearsal](results/board-rehearsal.json)')
    say('## Training signal')
    say('First test a battle-outcome-averaged **match-return** target, using 16 battle outcomes and at most three distinct public-value branches. Preserve the factual simulation, terminal objective, importance weights and opponents. The older M2 life-swing-only experiment lowered immediate noise but scored 49.5% directly against M1. The new proposal addresses the continuation and terminal terms that M2 left sampled. A matched M1/treatment test on two training seeds with large fixed-batch scoring and ranked-board checks fits a preallocated hour. Ranked opponents remain a separate, unapproved option. [Rationale, existing support, throughput arithmetic and test budget](signal.md)')
    (ROOT/'REPORT.md').write_text('\n\n'.join(paragraphs)+'\n')
if __name__=='__main__':main()
